/**
 * If a value is currently in error (eg. a required input was left blank, or a
 * number was above the allowed maximum), then the system will use this constant
 * to mark it as such.
 */
export const INVALID_VALUE = Symbol("InvalidValue");
export const OMIT_VALUE = Symbol("OmitValue");
export const PROCESSING_VALUE = Symbol("ProcessingValue");
/**
 * This constant is used to mark that data is starting to be calculated.
 */
export const PENDING = Symbol("Pending");
export function getOrNull(record, key) {
    return (record === null || record === void 0 ? void 0 : record.hasOwnProperty(key)) ? record[key] : null;
}
export function fullWidgetId(path, id, type) {
    const id_ = sanitizeId(id);
    const type_ = sanitizeId(type);
    return path.length
        ? `${path.map(sanitizeId).join("/")}/${id_}:${type}`
        : `${id_}:${type_}`;
}
/**
 * Sanitizes a string so that we are not susceptible to special characters
 * @param id the id
 * @returns the id with certain characters percent-encoded
 */
export function sanitizeId(id) {
    // eslint-disable-next-line no-useless-escape
    return id.replace(/[%\/:.]/g, (x) => `%${x.charCodeAt(0).toString(16)}`);
}
